{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.LONG_TAIL_MASTER_BIBLE as with a2 as ( select LEFT(sku,12) as sku2, count(marketplace) as online_free, count(case when order_date >= current_date - 30 then marketplace else null end ) as online_free_l30 from snitch_db.maplemonk.unicommerce_fact_items_intermediate where sku_group like \'%4MSFR%\' and selling_price < 30 and marketplace_mapped in (\'SHOPIFY\') group by 1 ), a1 as ( select LEFT(sku,12) as sku_group , count(marketplace) as offline_free, count(case when order_date >= current_date - 30 then marketplace else null end ) as offline_free_l30 from snitch_db.maplemonk.store_fact_items_offline where sku_group like \'%4MSFR%\' and selling_price < 10 group by 1 ), freegift as ( select coalesce(sku2,sku_group) as sku_group, online_free, offline_free, online_free_l30, offline_free_l30, (online_free + offline_free) as total_free, (online_free_l30 + offline_free_l30) as total_free_l30 from a2 o left join a1 f on o.sku2 = f.sku_group ), bible as ( select * from snitch_db.maplemonk.sku_master_v1 where sku_group like \'%4MSFR%\' ) select B.*, F.online_free, f.offline_free, f.offline_free_l30, f.online_free_l30, f.total_free, f.total_free_l30 from bible b left join freegift f on f.sku_group = b.sku_group ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.MTD_TARGET_perfumes as SELECT COALESCE(TRY_TO_DATE(\"Date \", \'DD/MM/YYYY\'), TRY_TO_DATE(\"Date \", \'DD-MM-YYYY\')) AS date, TRIM(\"Branch \") AS branch_code, ( REPLACE(\"Target \", \',\', \'\')::INT) * 0.03 AS target, ( REPLACE(\"MTD \", \',\', \'\')::INT) * 0.03 AS mtd_target FROM SNITCH_DB.MAPLEMONK.MTD_TARGET ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.MTD_TARGET_shoes as SELECT COALESCE(TRY_TO_DATE(\"Date \", \'DD/MM/YYYY\'), TRY_TO_DATE(\"Date \", \'DD-MM-YYYY\')) AS date, TRIM(\"Branch \") AS branch_code, ( REPLACE(\"Target \", \',\', \'\')::INT) * 0.02 AS target, ( REPLACE(\"MTD \", \',\', \'\')::INT) * 0.02 AS mtd_target FROM SNITCH_DB.MAPLEMONK.MTD_TARGET ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.long_tail_dsr_perfumes as WITH sales_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, sum(mrp*shipping_quantity) AS MRP_sales, sum(cogs_price*shipping_quantity) as cogs_sales, SUM(selling_price) AS gross_sales, COUNT(DISTINCT ORDER_NAME) AS bills, SUM(SUBORDER_QUANTITY) AS qty FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND sku_group NOT LIKE \'NT%\' AND DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') and sku_group like \'%4MSFR%\' GROUP BY 1, 2 ), returns_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, sum(mrp*shipping_quantity) AS mrp_returns, sum(cogs_price*shipping_quantity) as cogs_returns, SUM(selling_price) AS ret_sales, SUM(SUBORDER_QUANTITY) AS ret_qty FROM SNITCH_DB.MAPLEMONK.STORE_RETURNS_FACT_ITEMS WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND SKU_GROUP NOT LIKE \'NT%\' and order_name not like \'RTO%\' and sku_group like \'%4MSFR%\' GROUP BY 1, 2 ), multies_daily AS ( SELECT date, branch_code, COUNT(DISTINCT order_id) AS multies FROM ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, order_id, SUM(SHIPPING_QUANTITY) AS q FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE sku_group NOT LIKE \'CB%\' AND DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') and sku_group like \'%4MSFR%\' GROUP BY 1, 2, 3 ) WHERE q >= 2 GROUP BY 1, 2 ), omni_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, sum(shipping_quantity) as omni_sales_qty, SUM(selling_price) AS omni_sales FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND DOC_PREFIX IN (\'OMS\') and sku_group like \'%4MSFR%\' GROUP BY 1, 2 ), walkins_daily AS ( SELECT DATE_TRUNC(\'day\', order_date::DATE) AS date, round(code,0) AS branch_code, SUM(walk_ins) AS walk_ins FROM SNITCH_DB.MAPLEMONK.OFFLINE_WALKINS GROUP BY 1, 2 ), targets AS ( SELECT date, branch_code, target, mtd_target FROM SNITCH_DB.MAPLEMONK.MTD_TARGET_perfumes ), mapping AS ( SELECT branch_code, marketplace_mapped FROM ( SELECT branch_code, marketplace_mapped, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY DATE_TRUNC(\'day\', ORDER_TIMESTAMP) DESC) AS rn FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE ) WHERE rn = 1 ), net_daily AS ( SELECT s.date, s.branch_code, YEAR(s.date) AS yr, MONTH(s.date) AS mth, DAY(s.date) AS dom, s.gross_sales - COALESCE(r.ret_sales, 0) AS net_sales, s.MRP_sales - COALESCE(r.mrp_returns, 0) AS net_mrp, s.cogs_sales - COALESCE(r.cogs_returns, 0) as net_cogs, s.bills, s.qty - COALESCE(r.ret_qty, 0) AS net_qty, COALESCE(m.multies, 0) AS multies, COALESCE(o.omni_sales, 0) AS omni_sales, coalesce(o.omni_sales_qty,0) as omni_sales_qty, COALESCE(wk.walk_ins, 0) AS walk_ins FROM sales_daily s LEFT JOIN returns_daily r ON r.date = s.date AND LOWER(r.branch_code) = LOWER(s.branch_code) LEFT JOIN multies_daily m ON m.date = s.date AND LOWER(m.branch_code) = LOWER(s.branch_code) LEFT JOIN omni_daily o ON o.date = s.date AND LOWER(o.branch_code) = LOWER(s.branch_code) LEFT JOIN walkins_daily wk ON wk.date = s.date AND LOWER(wk.branch_code) = LOWER(s.branch_code) ), enriched AS ( SELECT nd.*, SUM(net_sales) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_sales, SUM(bills) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_bills, SUM(net_qty) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_qty, SUM(omni_sales) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_omni, SUM(omni_sales_qty) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_omni_qty, SUM(walk_ins) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_walkins, SUM(net_mrp) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_mrp, SUM(net_cogs) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) as mtd_cogs FROM net_daily nd ), inv_raw AS ( SELECT date, branch_code, base_stock, cluster, UPPER(sku_group) AS sku_group, inventory AS closing_inventory, fresh_inventory, new_category, COALESCE(NULLIF(dept_ideal, 0), 12) AS depth, XS_UNITS,S_UNITS,M_UNITS,L_UNITS,XL_UNITS,XXL_UNITS,XL3_UNITS,XL4_UNITS,XL5_UNITS,XL6_UNITS, JIT_XS_UNITS,JIT_S_UNITS,JIT_M_UNITS,JIT_L_UNITS,JIT_XL_UNITS,JIT_2XL_UNITS,JIT_3XL_UNITS,JIT_4XL_UNITS,JIT_5XL_UNITS,JIT_6XL_UNITS, CASE WHEN UPPER(sku_group) LIKE \'SH0%\' THEN CASE WHEN ( (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 THEN \'YES\' ELSE \'NO\' END WHEN UPPER(sku_group) LIKE \'4MBL%\' THEN CASE WHEN ( (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL3_UNITS + JIT_3XL_UNITS > 0 THEN 1 ELSE 0 END)) < 3 AND ( (CASE WHEN XS_UNITS + JIT_XS_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS + JIT_2XL_UNITS > 0 THEN 1 ELSE 0 END)) < 4 THEN \'YES\' ELSE \'NO\' END WHEN UPPER(SKU_GROUP) LIKE \'4MBG%\' OR UPPER(SKU_GROUP) LIKE \'4BRN%\' OR UPPER(SKU_GROUP) LIKE \'4BPL%\' OR UPPER(SKU_GROUP) LIKE \'4BTR%\' OR UPPER(SKU_GROUP) LIKE \'4BCH%\' OR UPPER(SKU_GROUP) LIKE \'4BJE%\' OR UPPER(SKU_GROUP) LIKE \'4BJK%\' OR UPPER(SKU_GROUP) LIKE \'4BSW%\' OR UPPER(SKU_GROUP) LIKE \'4BHD%\' OR UPPER(SKU_GROUP) LIKE \'4BOS%\' OR UPPER(SKU_GROUP) LIKE \'4BSHS%\' OR UPPER(SKU_GROUP) LIKE \'4BSFS%\' OR UPPER(SKU_GROUP) LIKE \'4BSH%\' OR UPPER(SKU_GROUP) LIKE \'4BBL%\' OR UPPER(SKU_GROUP) LIKE \'4BCA%\' OR UPPER(SKU_GROUP) LIKE \'4BSWT%\' OR UPPER(SKU_GROUP) LIKE \'4BCD%\' OR UPPER(SKU_GROUP) LIKE \'4BJO%\' THEN CASE WHEN ( (CASE WHEN XL3_UNITS + JIT_3XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL4_UNITS + JIT_4XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL5_UNITS + JIT_5XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL6_UNITS + JIT_6XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 THEN \'YES\' ELSE \'NO\' END ELSE CASE WHEN ( (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 OR ( (CASE WHEN XS_UNITS + JIT_XS_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS + JIT_2XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 4 THEN \'YES\' ELSE \'NO\' END END AS cut_size FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE INVENTORY + JIT_QTY > 0 and sku_group like \'%4MSFR%\' ), inv_bucketed AS ( SELECT date, branch_code, cluster, sku_group, closing_inventory, fresh_inventory, cut_size, new_category, base_stock, depth, CASE WHEN UPPER(new_category) IN (\'BAGS\',\'BELTS\',\'ACCESSORIES\',\'PERFUMES\',\'SHOES\',\'SUNGLASSES\',\'LUGGAGE\') THEN \'Long_Tail\' WHEN new_category IS NULL THEN NULL ELSE \'Apparel\' END AS category_bucket FROM inv_raw ), inv_agg AS ( SELECT date, branch_code, MAX(base_stock) AS base_stock, MAX(depth) AS depth, SUM(closing_inventory) AS total_inv, SUM(fresh_inventory) AS fresh_inv, SUM(CASE WHEN category_bucket = \'Apparel\' THEN closing_inventory END) AS apparel_inv, COUNT(DISTINCT CASE WHEN category_bucket = \'Apparel\' THEN sku_group END) AS total_options, COUNT(DISTINCT CASE WHEN cut_size = \'YES\' AND category_bucket = \'Apparel\' THEN sku_group END) AS cut_options, COUNT(DISTINCT CASE WHEN cut_size = \'NO\' AND category_bucket = \'Apparel\' THEN sku_group END) AS full_options FROM inv_bucketed WHERE category_bucket IS NOT NULL AND branch_code IS NOT NULL GROUP BY date, branch_code ), inv_metrics AS ( SELECT date, branch_code, COALESCE( base_stock, FIRST_VALUE(base_stock) IGNORE NULLS OVER ( PARTITION BY branch_code ORDER BY date ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING ), 0 ) AS base_stock, ROUND(DIV0( COALESCE( base_stock, FIRST_VALUE(base_stock) IGNORE NULLS OVER ( PARTITION BY branch_code ORDER BY date ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING ), 0 ), depth )) AS ideal_options, COALESCE(total_inv, 0) AS total_inv, COALESCE(fresh_inv, 0) AS fresh_inv, COALESCE(apparel_inv, 0) AS apparel_inv, COALESCE(total_options, 0) AS total_options, COALESCE(cut_options, 0) AS cut_options, COALESCE(full_options, 0) AS full_options FROM inv_agg ), cust_first AS ( SELECT phone_no, MIN(first_order_date) AS first_order_date FROM SNITCH_DB.MAPLEMONK.CUSTOMER_ACQ_DATE_CHANNEL GROUP BY phone_no ), seg_sales AS ( SELECT DATE_TRUNC(\'day\', f.ORDER_DATE::DATE) AS date, f.branch_code, CASE WHEN DATE_TRUNC(\'day\', f.ORDER_DATE::DATE) <= cf.first_order_date THEN \'new\' ELSE \'repeat\' END AS seg, COUNT(DISTINCT f.ORDER_NAME) AS bills, SUM(f.selling_price) AS gross_sales, SUM(f.mrp * f.shipping_quantity) AS mrp_gross, SUM(f.SUBORDER_QUANTITY) AS qty_gross FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE f LEFT JOIN cust_first cf ON cf.phone_no = \'+91\' || RIGHT(REGEXP_REPLACE(f.phone, \'[^0-9]\', \'\'), 10) WHERE f.ORDER_STATUS = \'Processed\' AND f.sku_group NOT LIKE \'CB%\' AND f.sku_group NOT LIKE \'NT%\' AND f.DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') GROUP BY 1, 2, 3 ), seg_returns AS ( SELECT DATE_TRUNC(\'day\', r.ORDER_DATE::DATE) AS date, r.branch_code, CASE WHEN DATE_TRUNC(\'day\', r.ORDER_DATE::DATE) <= cf.first_order_date THEN \'new\' ELSE \'repeat\' END AS seg, SUM(r.selling_price) AS ret_sales, SUM(r.mrp * r.shipping_quantity) AS mrp_ret, SUM(r.SUBORDER_QUANTITY) AS ret_qty FROM SNITCH_DB.MAPLEMONK.STORE_RETURNS_FACT_ITEMS r LEFT JOIN cust_first cf ON cf.phone_no = \'+91\' || RIGHT(REGEXP_REPLACE(r.phone, \'[^0-9]\', \'\'), 10) WHERE r.ORDER_STATUS = \'Processed\' AND r.category <> \'CARRY BAG\' GROUP BY 1, 2, 3 ), seg_net AS ( SELECT COALESCE(s.date, r.date) AS date, COALESCE(s.branch_code, r.branch_code) AS branch_code, COALESCE(s.seg, r.seg) AS seg, COALESCE(s.bills, 0) AS bills, COALESCE(s.gross_sales, 0) - COALESCE(r.ret_sales, 0) AS net_sales, COALESCE(s.mrp_gross, 0) - COALESCE(r.mrp_ret, 0) AS net_mrp, COALESCE(s.qty_gross, 0) - COALESCE(r.ret_qty, 0) AS net_qty, coalesce(s.gross_sales,0) as gross_sales, coalesce(r.ret_sales,0) as gross_returns FROM seg_sales s FULL OUTER JOIN seg_returns r ON r.date = s.date AND LOWER(r.branch_code) = LOWER(s.branch_code) AND r.seg = s.seg ), seg_daily AS ( SELECT date, branch_code, SUM(CASE WHEN seg = \'new\' THEN bills END) AS new_bills, SUM(CASE WHEN seg = \'new\' THEN net_sales END) AS new_sales, SUM(CASE WHEN seg = \'new\' THEN net_qty END) AS new_qty, SUM(CASE WHEN seg = \'new\' THEN net_mrp END) AS new_mrp, SUM(CASE WHEN seg = \'repeat\' THEN bills END) AS rpt_bills, SUM(CASE WHEN seg = \'repeat\' THEN net_sales END) AS rpt_sales, SUM(CASE WHEN seg = \'repeat\' THEN net_qty END) AS rpt_qty, SUM(CASE WHEN seg = \'repeat\' THEN net_mrp END) AS rpt_mrp FROM seg_net GROUP BY 1, 2 ), store_classification as ( select branch_code,location_simp,type_simp,city from snitch_db.maplemonk.offline_store_classification ) SELECT DATE_TRUNC(\'month\', e.date) AS month, e.date, e.branch_code, map.marketplace_mapped AS store_name, TRIM(SPLIT_PART(map.marketplace_mapped, \'-\', 2)) AS operating_model, UPPER(mo.STATE) AS STATE, mo.REGION, CASE WHEN UPPER(mo.PARTNER) IN (\'ABACUS AGENCIES INDIA PRIVATE LIMITED\') THEN \'ABACUS AGENCIES\' WHEN UPPER(mo.PARTNER) IN (\'KJ FASHION\') THEN \'KJ FASHION\' WHEN UPPER(mo.PARTNER) IN (\'SHIVERA LIFESTYLE\', \'SHIVERA LIFESTYLES PRIVATE LIMITED\') THEN \'DREAM SHIVERA PRIVATE LIMITED\' WHEN UPPER(mo.PARTNER) IN (\'SAPL\', \'SNITCH APPAREL PVT. LTD.\', \'SNITCH APPARELS PVT LTD\') THEN \'COCO\' ELSE UPPER(mo.PARTNER) END AS partner, UPPER(mo.AM) AS AM, mo.RM, mo.NSM, CASE WHEN E.BRANCH_CODE IN (\'104\',\'120\',\'123\',\'139\',\'146\',\'154\',\'155\',\'157\') THEN \'OUTLET\' WHEN UPPER(mo.STATE) IN (\'ASSAM\',\'BIHAR\',\'CHHATTISGARH\',\'ODHISSA\',\'PUNJAB\',\'RAJASTHAN\',\'WEST BENGAL\') THEN \'ANISHA\' WHEN UPPER(mo.STATE) IN (\'KARNATAKA\') THEN \'PRIYANKA\' WHEN UPPER(mo.STATE) IN (\'MAHARASHTRA\') THEN \'RASHMI\' WHEN UPPER(mo.STATE) IN (\'NEW DELHI\',\'HARYANA\',\'UTTAR PRADESH\',\'UTTARAKHAND\') THEN \'YUVRAJ\' WHEN UPPER(mo.STATE) IN (\'ANDHRA PRADESH\',\'TELANGANA\') THEN \'PREKSHYA\' WHEN UPPER(mo.STATE) IN (\'GUJARAT\',\'MADHYA PRADESH\') THEN \'APARNA\' WHEN UPPER(mo.STATE) IN (\'KERALA\',\'TAMIL NADU\') THEN \'P RAWAT\' ELSE \'UNKNOWN\' END AS MERCH_POC, CASE WHEN E.BRANCH_CODE IN (\'104\',\'120\',\'123\',\'139\',\'146\',\'154\',\'155\',\'157\') THEN \'OUTLET\' ELSE \'FRESH\' END AS STORE_STATUS, UPPER(SC.CITY) AS CITY, sc.location_simp as CITY_TYPE, sc.type_simp as LOCATION_TYPE, t.target, e.net_sales AS sales, DIV0(e.net_sales, t.target) AS ach_pct, DIV0(e.net_sales - w.net_sales, w.net_sales) AS wow_growth_pct, t.mtd_target, e.mtd_sales, DIV0(e.mtd_sales, t.mtd_target) AS mtd_ach_pct, e.mtd_sales AS mtd_sales_net, e.bills, e.net_qty AS qty, e.multies, e.net_mrp AS mrp_sales, e.mtd_mrp AS mrp_sales_mtd, e.net_cogs AS cogs_sales, e.mtd_cogs AS cogs_sales_mtd, DIV0(e.net_mrp - e.net_sales, e.net_mrp) AS disc_pct, DIV0(e.mtd_mrp - e.mtd_sales, e.mtd_mrp) AS disc_pct_mtd, DIV0(e.net_qty, e.bills) AS upt_today, DIV0(e.mtd_qty, e.mtd_bills) AS upt_mtd, DIV0(e.net_sales, e.bills) AS atv_today, DIV0(e.mtd_sales, e.mtd_bills) AS atv_mtd, DIV0(e.net_sales, e.net_qty) AS asp, sg.new_sales AS new_sales, sg.rpt_sales AS repeat_sales, sg.new_bills AS new_bills, sg.rpt_bills AS repeat_bills, sg.new_qty AS new_qty, sg.rpt_qty AS repeat_qty, sg.new_mrp AS new_mrp, sg.rpt_mrp AS repeat_mrp, DIV0(sg.new_qty, sg.new_bills) AS new_upt, DIV0(sg.rpt_qty, sg.rpt_bills) AS repeat_upt, DIV0(sg.new_sales, sg.new_bills) AS new_aov, DIV0(sg.rpt_sales, sg.rpt_bills) AS repeat_aov, DIV0(sg.new_mrp - sg.new_sales, sg.new_mrp) AS new_disc_pct, DIV0(sg.rpt_mrp - sg.rpt_sales, sg.rpt_mrp) AS repeat_disc_pct, ly.mtd_sales AS l2l_sales_25, e.mtd_sales AS l2l_sales_26, DIV0(e.mtd_sales - ly.mtd_sales, ly.mtd_sales) AS l2l_growth_pct, e.omni_sales AS omni_sales, e.mtd_omni AS omni_sales_mtd, e.omni_sales_qty AS omni_sales_qty, e.mtd_omni_qty AS omni_sales_qty_mtd, e.walk_ins AS footfall_today, e.mtd_walkins AS footfall_mtd, DIV0(e.bills, e.walk_ins) AS conversion_today, DIV0(e.mtd_bills, e.mtd_walkins) AS conversion_mtd, DIV0(e.walk_ins - w.walk_ins, w.walk_ins) AS ff_growth_pct, iv.base_stock, iv.ideal_options, iv.total_inv AS inv_total, iv.apparel_inv AS inv_apparel, iv.fresh_inv AS inv_fresh, iv.total_options, iv.cut_options, iv.full_options, FROM enriched e LEFT JOIN mapping map ON LOWER(map.branch_code) = LOWER(e.branch_code) LEFT JOIN SNITCH_DB.MAPLEMONK.MASTER_OFFINE mo ON TRIM(e.branch_code) = TRIM(mo.\"BRANCH CODE\") LEFT JOIN targets t ON t.date = e.date AND LOWER(t.branch_code) = LOWER(e.branch_code) LEFT JOIN enriched w ON w.branch_code = e.branch_code AND w.date = DATEADD(\'day\', -7, e.date) LEFT JOIN enriched ly ON ly.branch_code = e.branch_code AND ly.yr = e.yr - 1 AND ly.mth = e.mth AND ly.dom = e.dom LEFT JOIN inv_metrics iv ON iv.date = e.date AND LOWER(iv.branch_code) = LOWER(e.branch_code) LEFT JOIN seg_daily sg ON sg.date = e.date AND LOWER(sg.branch_code) = LOWER(e.branch_code) LEFT JOIN store_classification sc on LOWER(sc.branch_code) = LOWER(e.branch_code) WHERE map.marketplace_mapped NOT LIKE \'%- WH -%\' and map.marketplace_mapped NOT IN (\'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - SNITCH X\',\'SNITCH - FOCO - MAPLE MYSURU\'); CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.long_tail_dsr_shoes as WITH sales_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, sum(mrp*shipping_quantity) AS MRP_sales, sum(cogs_price*shipping_quantity) as cogs_sales, SUM(selling_price) AS gross_sales, COUNT(DISTINCT ORDER_NAME) AS bills, SUM(SUBORDER_QUANTITY) AS qty FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND sku_group NOT LIKE \'NT%\' AND DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') and sku_group like \'SH%\' GROUP BY 1, 2 ), returns_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, sum(mrp*shipping_quantity) AS mrp_returns, sum(cogs_price*shipping_quantity) as cogs_returns, SUM(selling_price) AS ret_sales, SUM(SUBORDER_QUANTITY) AS ret_qty FROM SNITCH_DB.MAPLEMONK.STORE_RETURNS_FACT_ITEMS WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND SKU_GROUP NOT LIKE \'NT%\' and order_name not like \'RTO%\' and sku_group like \'SH%\' GROUP BY 1, 2 ), multies_daily AS ( SELECT date, branch_code, COUNT(DISTINCT order_id) AS multies FROM ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, order_id, SUM(SHIPPING_QUANTITY) AS q FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE sku_group NOT LIKE \'CB%\' AND DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') and sku_group like \'SH%\' GROUP BY 1, 2, 3 ) WHERE q >= 2 GROUP BY 1, 2 ), omni_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, sum(shipping_quantity) as omni_sales_qty, SUM(selling_price) AS omni_sales FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND DOC_PREFIX IN (\'OMS\') and sku_group like \'SH%\' GROUP BY 1, 2 ), walkins_daily AS ( SELECT DATE_TRUNC(\'day\', order_date::DATE) AS date, round(code,0) AS branch_code, SUM(walk_ins) AS walk_ins FROM SNITCH_DB.MAPLEMONK.OFFLINE_WALKINS GROUP BY 1, 2 ), targets AS ( SELECT date, branch_code, target, mtd_target FROM SNITCH_DB.MAPLEMONK.MTD_TARGET_shoes ), mapping AS ( SELECT branch_code, marketplace_mapped FROM ( SELECT branch_code, marketplace_mapped, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY DATE_TRUNC(\'day\', ORDER_TIMESTAMP) DESC) AS rn FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE ) WHERE rn = 1 ), net_daily AS ( SELECT s.date, s.branch_code, YEAR(s.date) AS yr, MONTH(s.date) AS mth, DAY(s.date) AS dom, s.gross_sales - COALESCE(r.ret_sales, 0) AS net_sales, s.MRP_sales - COALESCE(r.mrp_returns, 0) AS net_mrp, s.cogs_sales - COALESCE(r.cogs_returns, 0) as net_cogs, s.bills, s.qty - COALESCE(r.ret_qty, 0) AS net_qty, COALESCE(m.multies, 0) AS multies, COALESCE(o.omni_sales, 0) AS omni_sales, coalesce(o.omni_sales_qty,0) as omni_sales_qty, COALESCE(wk.walk_ins, 0) AS walk_ins FROM sales_daily s LEFT JOIN returns_daily r ON r.date = s.date AND LOWER(r.branch_code) = LOWER(s.branch_code) LEFT JOIN multies_daily m ON m.date = s.date AND LOWER(m.branch_code) = LOWER(s.branch_code) LEFT JOIN omni_daily o ON o.date = s.date AND LOWER(o.branch_code) = LOWER(s.branch_code) LEFT JOIN walkins_daily wk ON wk.date = s.date AND LOWER(wk.branch_code) = LOWER(s.branch_code) ), enriched AS ( SELECT nd.*, SUM(net_sales) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_sales, SUM(bills) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_bills, SUM(net_qty) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_qty, SUM(omni_sales) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_omni, SUM(omni_sales_qty) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_omni_qty, SUM(walk_ins) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_walkins, SUM(net_mrp) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_mrp, SUM(net_cogs) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) as mtd_cogs FROM net_daily nd ), inv_raw AS ( SELECT date, branch_code, base_stock, cluster, UPPER(sku_group) AS sku_group, inventory AS closing_inventory, fresh_inventory, new_category, COALESCE(NULLIF(dept_ideal, 0), 12) AS depth, XS_UNITS,S_UNITS,M_UNITS,L_UNITS,XL_UNITS,XXL_UNITS,XL3_UNITS,XL4_UNITS,XL5_UNITS,XL6_UNITS, JIT_XS_UNITS,JIT_S_UNITS,JIT_M_UNITS,JIT_L_UNITS,JIT_XL_UNITS,JIT_2XL_UNITS,JIT_3XL_UNITS,JIT_4XL_UNITS,JIT_5XL_UNITS,JIT_6XL_UNITS, CASE WHEN UPPER(sku_group) LIKE \'SH0%\' THEN CASE WHEN ( (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 THEN \'YES\' ELSE \'NO\' END WHEN UPPER(sku_group) LIKE \'4MBL%\' THEN CASE WHEN ( (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL3_UNITS + JIT_3XL_UNITS > 0 THEN 1 ELSE 0 END)) < 3 AND ( (CASE WHEN XS_UNITS + JIT_XS_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS + JIT_2XL_UNITS > 0 THEN 1 ELSE 0 END)) < 4 THEN \'YES\' ELSE \'NO\' END WHEN UPPER(SKU_GROUP) LIKE \'4MBG%\' OR UPPER(SKU_GROUP) LIKE \'4BRN%\' OR UPPER(SKU_GROUP) LIKE \'4BPL%\' OR UPPER(SKU_GROUP) LIKE \'4BTR%\' OR UPPER(SKU_GROUP) LIKE \'4BCH%\' OR UPPER(SKU_GROUP) LIKE \'4BJE%\' OR UPPER(SKU_GROUP) LIKE \'4BJK%\' OR UPPER(SKU_GROUP) LIKE \'4BSW%\' OR UPPER(SKU_GROUP) LIKE \'4BHD%\' OR UPPER(SKU_GROUP) LIKE \'4BOS%\' OR UPPER(SKU_GROUP) LIKE \'4BSHS%\' OR UPPER(SKU_GROUP) LIKE \'4BSFS%\' OR UPPER(SKU_GROUP) LIKE \'4BSH%\' OR UPPER(SKU_GROUP) LIKE \'4BBL%\' OR UPPER(SKU_GROUP) LIKE \'4BCA%\' OR UPPER(SKU_GROUP) LIKE \'4BSWT%\' OR UPPER(SKU_GROUP) LIKE \'4BCD%\' OR UPPER(SKU_GROUP) LIKE \'4BJO%\' THEN CASE WHEN ( (CASE WHEN XL3_UNITS + JIT_3XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL4_UNITS + JIT_4XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL5_UNITS + JIT_5XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL6_UNITS + JIT_6XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 THEN \'YES\' ELSE \'NO\' END ELSE CASE WHEN ( (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 OR ( (CASE WHEN XS_UNITS + JIT_XS_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS + JIT_2XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 4 THEN \'YES\' ELSE \'NO\' END END AS cut_size FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE INVENTORY + JIT_QTY > 0 and sku_group like \'SH%\' ), inv_bucketed AS ( SELECT date, branch_code, cluster, sku_group, closing_inventory, fresh_inventory, cut_size, new_category, base_stock, depth, CASE WHEN UPPER(new_category) IN (\'BAGS\',\'BELTS\',\'ACCESSORIES\',\'PERFUMES\',\'SHOES\',\'SUNGLASSES\',\'LUGGAGE\') THEN \'Long_Tail\' WHEN new_category IS NULL THEN NULL ELSE \'Apparel\' END AS category_bucket FROM inv_raw ), inv_agg AS ( SELECT date, branch_code, MAX(base_stock) AS base_stock, MAX(depth) AS depth, SUM(closing_inventory) AS total_inv, SUM(fresh_inventory) AS fresh_inv, SUM(CASE WHEN category_bucket = \'Apparel\' THEN closing_inventory END) AS apparel_inv, COUNT(DISTINCT CASE WHEN category_bucket = \'Apparel\' THEN sku_group END) AS total_options, COUNT(DISTINCT CASE WHEN cut_size = \'YES\' AND category_bucket = \'Apparel\' THEN sku_group END) AS cut_options, COUNT(DISTINCT CASE WHEN cut_size = \'NO\' AND category_bucket = \'Apparel\' THEN sku_group END) AS full_options FROM inv_bucketed WHERE category_bucket IS NOT NULL AND branch_code IS NOT NULL GROUP BY date, branch_code ), inv_metrics AS ( SELECT date, branch_code, COALESCE( base_stock, FIRST_VALUE(base_stock) IGNORE NULLS OVER ( PARTITION BY branch_code ORDER BY date ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING ), 0 ) AS base_stock, ROUND(DIV0( COALESCE( base_stock, FIRST_VALUE(base_stock) IGNORE NULLS OVER ( PARTITION BY branch_code ORDER BY date ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING ), 0 ), depth )) AS ideal_options, COALESCE(total_inv, 0) AS total_inv, COALESCE(fresh_inv, 0) AS fresh_inv, COALESCE(apparel_inv, 0) AS apparel_inv, COALESCE(total_options, 0) AS total_options, COALESCE(cut_options, 0) AS cut_options, COALESCE(full_options, 0) AS full_options FROM inv_agg ), cust_first AS ( SELECT phone_no, MIN(first_order_date) AS first_order_date FROM SNITCH_DB.MAPLEMONK.CUSTOMER_ACQ_DATE_CHANNEL GROUP BY phone_no ), seg_sales AS ( SELECT DATE_TRUNC(\'day\', f.ORDER_DATE::DATE) AS date, f.branch_code, CASE WHEN DATE_TRUNC(\'day\', f.ORDER_DATE::DATE) <= cf.first_order_date THEN \'new\' ELSE \'repeat\' END AS seg, COUNT(DISTINCT f.ORDER_NAME) AS bills, SUM(f.selling_price) AS gross_sales, SUM(f.mrp * f.shipping_quantity) AS mrp_gross, SUM(f.SUBORDER_QUANTITY) AS qty_gross FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE f LEFT JOIN cust_first cf ON cf.phone_no = \'+91\' || RIGHT(REGEXP_REPLACE(f.phone, \'[^0-9]\', \'\'), 10) WHERE f.ORDER_STATUS = \'Processed\' AND f.sku_group NOT LIKE \'CB%\' AND f.sku_group NOT LIKE \'NT%\' AND f.DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') GROUP BY 1, 2, 3 ), seg_returns AS ( SELECT DATE_TRUNC(\'day\', r.ORDER_DATE::DATE) AS date, r.branch_code, CASE WHEN DATE_TRUNC(\'day\', r.ORDER_DATE::DATE) <= cf.first_order_date THEN \'new\' ELSE \'repeat\' END AS seg, SUM(r.selling_price) AS ret_sales, SUM(r.mrp * r.shipping_quantity) AS mrp_ret, SUM(r.SUBORDER_QUANTITY) AS ret_qty FROM SNITCH_DB.MAPLEMONK.STORE_RETURNS_FACT_ITEMS r LEFT JOIN cust_first cf ON cf.phone_no = \'+91\' || RIGHT(REGEXP_REPLACE(r.phone, \'[^0-9]\', \'\'), 10) WHERE r.ORDER_STATUS = \'Processed\' AND r.category <> \'CARRY BAG\' GROUP BY 1, 2, 3 ), seg_net AS ( SELECT COALESCE(s.date, r.date) AS date, COALESCE(s.branch_code, r.branch_code) AS branch_code, COALESCE(s.seg, r.seg) AS seg, COALESCE(s.bills, 0) AS bills, COALESCE(s.gross_sales, 0) - COALESCE(r.ret_sales, 0) AS net_sales, COALESCE(s.mrp_gross, 0) - COALESCE(r.mrp_ret, 0) AS net_mrp, COALESCE(s.qty_gross, 0) - COALESCE(r.ret_qty, 0) AS net_qty, coalesce(s.gross_sales,0) as gross_sales, coalesce(r.ret_sales,0) as gross_returns FROM seg_sales s FULL OUTER JOIN seg_returns r ON r.date = s.date AND LOWER(r.branch_code) = LOWER(s.branch_code) AND r.seg = s.seg ), seg_daily AS ( SELECT date, branch_code, SUM(CASE WHEN seg = \'new\' THEN bills END) AS new_bills, SUM(CASE WHEN seg = \'new\' THEN net_sales END) AS new_sales, SUM(CASE WHEN seg = \'new\' THEN net_qty END) AS new_qty, SUM(CASE WHEN seg = \'new\' THEN net_mrp END) AS new_mrp, SUM(CASE WHEN seg = \'repeat\' THEN bills END) AS rpt_bills, SUM(CASE WHEN seg = \'repeat\' THEN net_sales END) AS rpt_sales, SUM(CASE WHEN seg = \'repeat\' THEN net_qty END) AS rpt_qty, SUM(CASE WHEN seg = \'repeat\' THEN net_mrp END) AS rpt_mrp FROM seg_net GROUP BY 1, 2 ), store_classification as ( select branch_code,location_simp,type_simp,city from snitch_db.maplemonk.offline_store_classification ) SELECT DATE_TRUNC(\'month\', e.date) AS month, e.date, e.branch_code, map.marketplace_mapped AS store_name, TRIM(SPLIT_PART(map.marketplace_mapped, \'-\', 2)) AS operating_model, UPPER(mo.STATE) AS STATE, mo.REGION, CASE WHEN UPPER(mo.PARTNER) IN (\'ABACUS AGENCIES INDIA PRIVATE LIMITED\') THEN \'ABACUS AGENCIES\' WHEN UPPER(mo.PARTNER) IN (\'KJ FASHION\') THEN \'KJ FASHION\' WHEN UPPER(mo.PARTNER) IN (\'SHIVERA LIFESTYLE\', \'SHIVERA LIFESTYLES PRIVATE LIMITED\') THEN \'DREAM SHIVERA PRIVATE LIMITED\' WHEN UPPER(mo.PARTNER) IN (\'SAPL\', \'SNITCH APPAREL PVT. LTD.\', \'SNITCH APPARELS PVT LTD\') THEN \'COCO\' ELSE UPPER(mo.PARTNER) END AS partner, UPPER(mo.AM) AS AM, mo.RM, mo.NSM, CASE WHEN E.BRANCH_CODE IN (\'104\',\'120\',\'123\',\'139\',\'146\',\'154\',\'155\',\'157\') THEN \'OUTLET\' WHEN UPPER(mo.STATE) IN (\'ASSAM\',\'BIHAR\',\'CHHATTISGARH\',\'ODHISSA\',\'PUNJAB\',\'RAJASTHAN\',\'WEST BENGAL\') THEN \'ANISHA\' WHEN UPPER(mo.STATE) IN (\'KARNATAKA\') THEN \'PRIYANKA\' WHEN UPPER(mo.STATE) IN (\'MAHARASHTRA\') THEN \'RASHMI\' WHEN UPPER(mo.STATE) IN (\'NEW DELHI\',\'HARYANA\',\'UTTAR PRADESH\',\'UTTARAKHAND\') THEN \'YUVRAJ\' WHEN UPPER(mo.STATE) IN (\'ANDHRA PRADESH\',\'TELANGANA\') THEN \'PREKSHYA\' WHEN UPPER(mo.STATE) IN (\'GUJARAT\',\'MADHYA PRADESH\') THEN \'APARNA\' WHEN UPPER(mo.STATE) IN (\'KERALA\',\'TAMIL NADU\') THEN \'P RAWAT\' ELSE \'UNKNOWN\' END AS MERCH_POC, CASE WHEN E.BRANCH_CODE IN (\'104\',\'120\',\'123\',\'139\',\'146\',\'154\',\'155\',\'157\') THEN \'OUTLET\' ELSE \'FRESH\' END AS STORE_STATUS, UPPER(SC.CITY) AS CITY, sc.location_simp as CITY_TYPE, sc.type_simp as LOCATION_TYPE, t.target, e.net_sales AS sales, DIV0(e.net_sales, t.target) AS ach_pct, DIV0(e.net_sales - w.net_sales, w.net_sales) AS wow_growth_pct, t.mtd_target, e.mtd_sales, DIV0(e.mtd_sales, t.mtd_target) AS mtd_ach_pct, e.mtd_sales AS mtd_sales_net, e.bills, e.net_qty AS qty, e.multies, e.net_mrp AS mrp_sales, e.mtd_mrp AS mrp_sales_mtd, e.net_cogs AS cogs_sales, e.mtd_cogs AS cogs_sales_mtd, DIV0(e.net_mrp - e.net_sales, e.net_mrp) AS disc_pct, DIV0(e.mtd_mrp - e.mtd_sales, e.mtd_mrp) AS disc_pct_mtd, DIV0(e.net_qty, e.bills) AS upt_today, DIV0(e.mtd_qty, e.mtd_bills) AS upt_mtd, DIV0(e.net_sales, e.bills) AS atv_today, DIV0(e.mtd_sales, e.mtd_bills) AS atv_mtd, DIV0(e.net_sales, e.net_qty) AS asp, sg.new_sales AS new_sales, sg.rpt_sales AS repeat_sales, sg.new_bills AS new_bills, sg.rpt_bills AS repeat_bills, sg.new_qty AS new_qty, sg.rpt_qty AS repeat_qty, sg.new_mrp AS new_mrp, sg.rpt_mrp AS repeat_mrp, DIV0(sg.new_qty, sg.new_bills) AS new_upt, DIV0(sg.rpt_qty, sg.rpt_bills) AS repeat_upt, DIV0(sg.new_sales, sg.new_bills) AS new_aov, DIV0(sg.rpt_sales, sg.rpt_bills) AS repeat_aov, DIV0(sg.new_mrp - sg.new_sales, sg.new_mrp) AS new_disc_pct, DIV0(sg.rpt_mrp - sg.rpt_sales, sg.rpt_mrp) AS repeat_disc_pct, ly.mtd_sales AS l2l_sales_25, e.mtd_sales AS l2l_sales_26, DIV0(e.mtd_sales - ly.mtd_sales, ly.mtd_sales) AS l2l_growth_pct, e.omni_sales AS omni_sales, e.mtd_omni AS omni_sales_mtd, e.omni_sales_qty AS omni_sales_qty, e.mtd_omni_qty AS omni_sales_qty_mtd, e.walk_ins AS footfall_today, e.mtd_walkins AS footfall_mtd, DIV0(e.bills, e.walk_ins) AS conversion_today, DIV0(e.mtd_bills, e.mtd_walkins) AS conversion_mtd, DIV0(e.walk_ins - w.walk_ins, w.walk_ins) AS ff_growth_pct, iv.base_stock, iv.ideal_options, iv.total_inv AS inv_total, iv.apparel_inv AS inv_apparel, iv.fresh_inv AS inv_fresh, iv.total_options, iv.cut_options, iv.full_options, FROM enriched e LEFT JOIN mapping map ON LOWER(map.branch_code) = LOWER(e.branch_code) LEFT JOIN SNITCH_DB.MAPLEMONK.MASTER_OFFINE mo ON TRIM(e.branch_code) = TRIM(mo.\"BRANCH CODE\") LEFT JOIN targets t ON t.date = e.date AND LOWER(t.branch_code) = LOWER(e.branch_code) LEFT JOIN enriched w ON w.branch_code = e.branch_code AND w.date = DATEADD(\'day\', -7, e.date) LEFT JOIN enriched ly ON ly.branch_code = e.branch_code AND ly.yr = e.yr - 1 AND ly.mth = e.mth AND ly.dom = e.dom LEFT JOIN inv_metrics iv ON iv.date = e.date AND LOWER(iv.branch_code) = LOWER(e.branch_code) LEFT JOIN seg_daily sg ON sg.date = e.date AND LOWER(sg.branch_code) = LOWER(e.branch_code) LEFT JOIN store_classification sc on LOWER(sc.branch_code) = LOWER(e.branch_code) WHERE map.marketplace_mapped NOT LIKE \'%- WH -%\' and map.marketplace_mapped NOT IN (\'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - SNITCH X\',\'SNITCH - FOCO - MAPLE MYSURU\'); CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.long_tail_dsr as WITH sales_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, SUM(selling_price) AS gross_sales, COUNT(DISTINCT ORDER_NAME) AS bills, SUM(SUBORDER_QUANTITY) AS qty, sum (case when sku_group like \'%4MSFR%\' then selling_price else null end ) as perf_sales, sum (case when sku_group like \'%4MTL0%\' then selling_price else null end ) as trolley_sales, sum (case when sku_group like \'SH%\' then selling_price else null end ) as shoes_sales, sum (case when sku_group like \'%4MSFR%\' then suborder_quantity else null end ) as perf_qty, sum (case when sku_group like \'%4MTL0%\' then suborder_quantity else null end ) as trolley_qty, sum (case when sku_group like \'SH%\' then suborder_quantity else null end ) as shoes_qty, COUNT(DISTINCT CASE WHEN sku_group like \'%4MSFR%\' then ORDER_NAME else null end) AS perf_bills, COUNT(DISTINCT CASE WHEN sku_group like \'SH%\' then ORDER_NAME else null end) AS shoes_bills, COUNT(DISTINCT CASE WHEN sku_group like \'%4MTL0%\' then ORDER_NAME else null end) AS trolley_bills, sum (case when sku_group like \'%4MSFR%\' and selling_price < 10 then suborder_quantity else null end ) as perf_free_qty, COUNT(DISTINCT CASE WHEN sku_group like \'%4MSFR%\' and selling_price < 10 then ORDER_NAME else null end) AS perf_free_bills, FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND sku_group NOT LIKE \'NT%\' AND DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') and order_date >= \'2026-09-01\' GROUP BY 1, 2 ), returns_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, SUM(selling_price) AS ret_sales, SUM(SUBORDER_QUANTITY) AS ret_qty FROM SNITCH_DB.MAPLEMONK.STORE_RETURNS_FACT_ITEMS WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND SKU_GROUP NOT LIKE \'NT%\' and order_name not like \'RTO%\' and order_date >= \'2026-09-01\' GROUP BY 1, 2 ), multies_daily AS ( SELECT date, branch_code, COUNT(DISTINCT order_id) AS multies FROM ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, order_id, SUM(SHIPPING_QUANTITY) AS q FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE sku_group NOT LIKE \'CB%\' AND DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') and order_date >= \'2026-09-01\' GROUP BY 1, 2, 3 ) WHERE q >= 2 GROUP BY 1, 2 ), omni_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, sum(shipping_quantity) as omni_sales_qty, SUM(selling_price) AS omni_sales FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND DOC_PREFIX IN (\'OMS\') and order_date >= \'2026-09-01\' GROUP BY 1, 2 ), walkins_daily AS ( SELECT DATE_TRUNC(\'day\', order_date::DATE) AS date, round(code,0) AS branch_code, SUM(walk_ins) AS walk_ins FROM SNITCH_DB.MAPLEMONK.OFFLINE_WALKINS where order_date >= \'2026-09-01\' GROUP BY 1, 2 ), targets AS ( SELECT COALESCE(TRY_TO_DATE(\"Date \", \'DD/MM/YYYY\'), TRY_TO_DATE(\"Date \", \'DD-MM-YYYY\')) AS date, TRIM(\"Branch \") AS branch_code, REPLACE(\"Target \", \',\', \'\')::INT AS target, REPLACE(\"MTD \", \',\', \'\')::INT AS mtd_target FROM SNITCH_DB.MAPLEMONK.MTD_TARGET where date >= \'2026-09-01\' ), mapping AS ( SELECT branch_code, marketplace_mapped FROM ( SELECT branch_code, marketplace_mapped, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY DATE_TRUNC(\'day\', ORDER_TIMESTAMP) DESC) AS rn FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE where order_date >= \'2026-09-01\' ) WHERE rn = 1 ), net_daily AS ( SELECT s.date, s.branch_code, YEAR(s.date) AS yr, MONTH(s.date) AS mth, DAY(s.date) AS dom, s.gross_sales - COALESCE(r.ret_sales, 0) AS net_sales, s.bills, s.qty - COALESCE(r.ret_qty, 0) AS net_qty, COALESCE(m.multies, 0) AS multies, COALESCE(o.omni_sales, 0) AS omni_sales, coalesce(o.omni_sales_qty,0) as omni_sales_qty, COALESCE(wk.walk_ins, 0) AS walk_ins, perf_sales, trolley_sales, shoes_sales, perf_qty, trolley_qty, shoes_qty, perf_bills, shoes_bills, trolley_bills, perf_free_qty, perf_free_bills, FROM sales_daily s LEFT JOIN returns_daily r ON r.date = s.date AND LOWER(r.branch_code) = LOWER(s.branch_code) LEFT JOIN multies_daily m ON m.date = s.date AND LOWER(m.branch_code) = LOWER(s.branch_code) LEFT JOIN omni_daily o ON o.date = s.date AND LOWER(o.branch_code) = LOWER(s.branch_code) LEFT JOIN walkins_daily wk ON wk.date = s.date AND LOWER(wk.branch_code) = LOWER(s.branch_code) ), enriched AS ( SELECT nd.*, SUM(net_sales) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_sales, SUM(bills) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_bills, SUM(net_qty) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_qty, SUM(omni_sales) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_omni, SUM(omni_sales_qty) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_omni_qty, SUM(walk_ins) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_walkins, FROM net_daily nd ), inv_raw AS ( SELECT date, branch_code, base_stock, cluster, UPPER(sku_group) AS sku_group, inventory AS closing_inventory, fresh_inventory, new_category, COALESCE(NULLIF(dept_ideal, 0), 12) AS depth, XS_UNITS,S_UNITS,M_UNITS,L_UNITS,XL_UNITS,XXL_UNITS,XL3_UNITS,XL4_UNITS,XL5_UNITS,XL6_UNITS, JIT_XS_UNITS,JIT_S_UNITS,JIT_M_UNITS,JIT_L_UNITS,JIT_XL_UNITS,JIT_2XL_UNITS,JIT_3XL_UNITS,JIT_4XL_UNITS,JIT_5XL_UNITS,JIT_6XL_UNITS, CASE WHEN UPPER(sku_group) LIKE \'SH0%\' THEN CASE WHEN ( (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 THEN \'YES\' ELSE \'NO\' END WHEN UPPER(sku_group) LIKE \'4MBL%\' THEN CASE WHEN ( (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL3_UNITS + JIT_3XL_UNITS > 0 THEN 1 ELSE 0 END)) < 3 AND ( (CASE WHEN XS_UNITS + JIT_XS_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS + JIT_2XL_UNITS > 0 THEN 1 ELSE 0 END)) < 4 THEN \'YES\' ELSE \'NO\' END WHEN UPPER(SKU_GROUP) LIKE \'4MBG%\' OR UPPER(SKU_GROUP) LIKE \'4BRN%\' OR UPPER(SKU_GROUP) LIKE \'4BPL%\' OR UPPER(SKU_GROUP) LIKE \'4BTR%\' OR UPPER(SKU_GROUP) LIKE \'4BCH%\' OR UPPER(SKU_GROUP) LIKE \'4BJE%\' OR UPPER(SKU_GROUP) LIKE \'4BJK%\' OR UPPER(SKU_GROUP) LIKE \'4BSW%\' OR UPPER(SKU_GROUP) LIKE \'4BHD%\' OR UPPER(SKU_GROUP) LIKE \'4BOS%\' OR UPPER(SKU_GROUP) LIKE \'4BSHS%\' OR UPPER(SKU_GROUP) LIKE \'4BSFS%\' OR UPPER(SKU_GROUP) LIKE \'4BSH%\' OR UPPER(SKU_GROUP) LIKE \'4BBL%\' OR UPPER(SKU_GROUP) LIKE \'4BCA%\' OR UPPER(SKU_GROUP) LIKE \'4BSWT%\' OR UPPER(SKU_GROUP) LIKE \'4BCD%\' OR UPPER(SKU_GROUP) LIKE \'4BJO%\' THEN CASE WHEN ( (CASE WHEN XL3_UNITS + JIT_3XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL4_UNITS + JIT_4XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL5_UNITS + JIT_5XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL6_UNITS + JIT_6XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 THEN \'YES\' ELSE \'NO\' END ELSE CASE WHEN ( (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 OR ( (CASE WHEN XS_UNITS + JIT_XS_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS + JIT_2XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 4 THEN \'YES\' ELSE \'NO\' END END AS cut_size FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE INVENTORY + JIT_QTY > 0 ), inv_bucketed AS ( SELECT date, branch_code, cluster, sku_group, closing_inventory, fresh_inventory, cut_size, new_category, base_stock, depth, CASE WHEN UPPER(new_category) IN (\'BAGS\',\'BELTS\',\'ACCESSORIES\',\'PERFUMES\',\'SHOES\',\'SUNGLASSES\',\'LUGGAGE\') THEN \'Long_Tail\' WHEN new_category IS NULL THEN NULL ELSE \'Apparel\' END AS category_bucket FROM inv_raw ), inv_agg AS ( SELECT date, branch_code, MAX(base_stock) AS base_stock, MAX(depth) AS depth, SUM(closing_inventory) AS total_inv, SUM(fresh_inventory) AS fresh_inv, SUM(CASE WHEN category_bucket = \'Apparel\' THEN closing_inventory END) AS apparel_inv, COUNT(DISTINCT CASE WHEN category_bucket = \'Apparel\' THEN sku_group END) AS total_options, COUNT(DISTINCT CASE WHEN cut_size = \'YES\' AND category_bucket = \'Apparel\' THEN sku_group END) AS cut_options, COUNT(DISTINCT CASE WHEN cut_size = \'NO\' AND category_bucket = \'Apparel\' THEN sku_group END) AS full_options FROM inv_bucketed WHERE category_bucket IS NOT NULL AND branch_code IS NOT NULL GROUP BY date, branch_code ), inv_metrics AS ( SELECT date, branch_code, COALESCE( base_stock, FIRST_VALUE(base_stock) IGNORE NULLS OVER ( PARTITION BY branch_code ORDER BY date ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING ), 0 ) AS base_stock, ROUND(DIV0( COALESCE( base_stock, FIRST_VALUE(base_stock) IGNORE NULLS OVER ( PARTITION BY branch_code ORDER BY date ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING ), 0 ), depth )) AS ideal_options, COALESCE(total_inv, 0) AS total_inv, COALESCE(fresh_inv, 0) AS fresh_inv, COALESCE(apparel_inv, 0) AS apparel_inv, COALESCE(total_options, 0) AS total_options, COALESCE(cut_options, 0) AS cut_options, COALESCE(full_options, 0) AS full_options FROM inv_agg ), cust_first AS ( SELECT phone_no, MIN(first_order_date) AS first_order_date FROM SNITCH_DB.MAPLEMONK.CUSTOMER_ACQ_DATE_CHANNEL GROUP BY phone_no ), seg_sales AS ( SELECT DATE_TRUNC(\'day\', f.ORDER_DATE::DATE) AS date, f.branch_code, CASE WHEN DATE_TRUNC(\'day\', f.ORDER_DATE::DATE) <= cf.first_order_date THEN \'new\' ELSE \'repeat\' END AS seg, COUNT(DISTINCT f.ORDER_NAME) AS bills, SUM(f.selling_price) AS gross_sales, SUM(f.mrp * f.shipping_quantity) AS mrp_gross, SUM(f.SUBORDER_QUANTITY) AS qty_gross FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE f LEFT JOIN cust_first cf ON cf.phone_no = \'+91\' || RIGHT(REGEXP_REPLACE(f.phone, \'[^0-9]\', \'\'), 10) WHERE f.ORDER_STATUS = \'Processed\' AND f.sku_group NOT LIKE \'CB%\' AND f.sku_group NOT LIKE \'NT%\' AND f.DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') GROUP BY 1, 2, 3 ), seg_returns AS ( SELECT DATE_TRUNC(\'day\', r.ORDER_DATE::DATE) AS date, r.branch_code, CASE WHEN DATE_TRUNC(\'day\', r.ORDER_DATE::DATE) <= cf.first_order_date THEN \'new\' ELSE \'repeat\' END AS seg, SUM(r.selling_price) AS ret_sales, SUM(r.mrp * r.shipping_quantity) AS mrp_ret, SUM(r.SUBORDER_QUANTITY) AS ret_qty FROM SNITCH_DB.MAPLEMONK.STORE_RETURNS_FACT_ITEMS r LEFT JOIN cust_first cf ON cf.phone_no = \'+91\' || RIGHT(REGEXP_REPLACE(r.phone, \'[^0-9]\', \'\'), 10) WHERE r.ORDER_STATUS = \'Processed\' AND r.category <> \'CARRY BAG\' GROUP BY 1, 2, 3 ), seg_net AS ( SELECT COALESCE(s.date, r.date) AS date, COALESCE(s.branch_code, r.branch_code) AS branch_code, COALESCE(s.seg, r.seg) AS seg, COALESCE(s.bills, 0) AS bills, COALESCE(s.gross_sales, 0) - COALESCE(r.ret_sales, 0) AS net_sales, COALESCE(s.mrp_gross, 0) - COALESCE(r.mrp_ret, 0) AS net_mrp, COALESCE(s.qty_gross, 0) - COALESCE(r.ret_qty, 0) AS net_qty, coalesce(s.gross_sales,0) as gross_sales, coalesce(r.ret_sales,0) as gross_returns FROM seg_sales s FULL OUTER JOIN seg_returns r ON r.date = s.date AND LOWER(r.branch_code) = LOWER(s.branch_code) AND r.seg = s.seg ), seg_daily AS ( SELECT date, branch_code, SUM(CASE WHEN seg = \'new\' THEN bills END) AS new_bills, SUM(CASE WHEN seg = \'new\' THEN net_sales END) AS new_sales, SUM(CASE WHEN seg = \'new\' THEN net_qty END) AS new_qty, SUM(CASE WHEN seg = \'new\' THEN net_mrp END) AS new_mrp, SUM(CASE WHEN seg = \'repeat\' THEN bills END) AS rpt_bills, SUM(CASE WHEN seg = \'repeat\' THEN net_sales END) AS rpt_sales, SUM(CASE WHEN seg = \'repeat\' THEN net_qty END) AS rpt_qty, SUM(CASE WHEN seg = \'repeat\' THEN net_mrp END) AS rpt_mrp FROM seg_net GROUP BY 1, 2 ), store_classification as ( select branch_code,location_simp,type_simp,city from snitch_db.maplemonk.offline_store_classification ) SELECT DATE_TRUNC(\'month\', e.date) AS month, e.date, e.branch_code, map.marketplace_mapped AS store_name, TRIM(SPLIT_PART(map.marketplace_mapped, \'-\', 2)) AS operating_model, UPPER(mo.STATE) AS STATE, mo.REGION, CASE WHEN UPPER(mo.PARTNER) IN (\'ABACUS AGENCIES INDIA PRIVATE LIMITED\') THEN \'ABACUS AGENCIES\' WHEN UPPER(mo.PARTNER) IN (\'KJ FASHION\') THEN \'KJ FASHION\' WHEN UPPER(mo.PARTNER) IN (\'SHIVERA LIFESTYLE\', \'SHIVERA LIFESTYLES PRIVATE LIMITED\') THEN \'DREAM SHIVERA PRIVATE LIMITED\' WHEN UPPER(mo.PARTNER) IN (\'SAPL\', \'SNITCH APPAREL PVT. LTD.\', \'SNITCH APPARELS PVT LTD\') THEN \'COCO\' ELSE UPPER(mo.PARTNER) END AS partner, UPPER(mo.AM) AS AM, mo.RM, mo.NSM, CASE WHEN E.BRANCH_CODE IN (\'104\',\'120\',\'123\',\'139\',\'146\',\'154\',\'155\',\'157\') THEN \'OUTLET\' WHEN UPPER(mo.STATE) IN (\'ASSAM\',\'BIHAR\',\'CHHATTISGARH\',\'ODHISSA\',\'PUNJAB\',\'RAJASTHAN\',\'WEST BENGAL\') THEN \'ANISHA\' WHEN UPPER(mo.STATE) IN (\'KARNATAKA\') THEN \'PRIYANKA\' WHEN UPPER(mo.STATE) IN (\'MAHARASHTRA\') THEN \'RASHMI\' WHEN UPPER(mo.STATE) IN (\'NEW DELHI\',\'HARYANA\',\'UTTAR PRADESH\',\'UTTARAKHAND\') THEN \'YUVRAJ\' WHEN UPPER(mo.STATE) IN (\'ANDHRA PRADESH\',\'TELANGANA\') THEN \'PREKSHYA\' WHEN UPPER(mo.STATE) IN (\'GUJARAT\',\'MADHYA PRADESH\') THEN \'APARNA\' WHEN UPPER(mo.STATE) IN (\'KERALA\',\'TAMIL NADU\') THEN \'P RAWAT\' ELSE \'UNKNOWN\' END AS MERCH_POC, CASE WHEN E.BRANCH_CODE IN (\'104\',\'120\',\'123\',\'139\',\'146\',\'154\',\'155\',\'157\') THEN \'OUTLET\' ELSE \'FRESH\' END AS STORE_STATUS, UPPER(SC.CITY) AS CITY, sc.location_simp as CITY_TYPE, sc.type_simp as LOCATION_TYPE, t.target, e.net_sales AS sales, DIV0(e.net_sales, t.target) AS ach_pct, DIV0(e.net_sales - w.net_sales, w.net_sales) AS wow_growth_pct, t.mtd_target, e.mtd_sales, DIV0(e.mtd_sales, t.mtd_target) AS mtd_ach_pct, e.mtd_sales AS mtd_sales_net, e.bills, e.net_qty AS qty, e.multies, DIV0(e.net_qty, e.bills) AS upt_today, DIV0(e.mtd_qty, e.mtd_bills) AS upt_mtd, DIV0(e.net_sales, e.bills) AS atv_today, DIV0(e.mtd_sales, e.mtd_bills) AS atv_mtd, DIV0(e.net_sales, e.net_qty) AS asp, sg.new_sales AS new_sales, sg.rpt_sales AS repeat_sales, sg.new_bills AS new_bills, sg.rpt_bills AS repeat_bills, sg.new_qty AS new_qty, sg.rpt_qty AS repeat_qty, DIV0(sg.new_qty, sg.new_bills) AS new_upt, DIV0(sg.rpt_qty, sg.rpt_bills) AS repeat_upt, DIV0(sg.new_sales, sg.new_bills) AS new_aov, DIV0(sg.rpt_sales, sg.rpt_bills) AS repeat_aov, ly.mtd_sales AS l2l_sales_25, e.mtd_sales AS l2l_sales_26, DIV0(e.mtd_sales - ly.mtd_sales, ly.mtd_sales) AS l2l_growth_pct, e.omni_sales AS omni_sales, e.mtd_omni AS omni_sales_mtd, e.omni_sales_qty AS omni_sales_qty, e.mtd_omni_qty AS omni_sales_qty_mtd, e.walk_ins AS footfall_today, e.mtd_walkins AS footfall_mtd, DIV0(e.bills, e.walk_ins) AS conversion_today, DIV0(e.mtd_bills, e.mtd_walkins) AS conversion_mtd, DIV0(e.walk_ins - w.walk_ins, w.walk_ins) AS ff_growth_pct, iv.base_stock, e.perf_sales, e.trolley_sales, e.shoes_sales, e.perf_qty, e.trolley_qty, e.shoes_qty, e.perf_bills, e.shoes_bills, e.trolley_bills, e.perf_free_qty, e.perf_free_bills, FROM enriched e LEFT JOIN mapping map ON LOWER(map.branch_code) = LOWER(e.branch_code) LEFT JOIN SNITCH_DB.MAPLEMONK.MASTER_OFFINE mo ON TRIM(e.branch_code) = TRIM(mo.\"BRANCH CODE\") LEFT JOIN targets t ON t.date = e.date AND LOWER(t.branch_code) = LOWER(e.branch_code) LEFT JOIN enriched w ON w.branch_code = e.branch_code AND w.date = DATEADD(\'day\', -7, e.date) LEFT JOIN enriched ly ON ly.branch_code = e.branch_code AND ly.yr = e.yr - 1 AND ly.mth = e.mth AND ly.dom = e.dom LEFT JOIN inv_metrics iv ON iv.date = e.date AND LOWER(iv.branch_code) = LOWER(e.branch_code) LEFT JOIN seg_daily sg ON sg.date = e.date AND LOWER(sg.branch_code) = LOWER(e.branch_code) LEFT JOIN store_classification sc on LOWER(sc.branch_code) = LOWER(e.branch_code) WHERE map.marketplace_mapped NOT LIKE \'%- WH -%\' and map.marketplace_mapped NOT IN (\'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - SNITCH X\',\'SNITCH - FOCO - MAPLE MYSURU\') ; CREATE OR REPLACE TABLE snitch_db.maplemonk.customer_acq_date_channel_sku AS WITH perfume_orders AS ( SELECT \'+91\' || RIGHT( REGEXP_REPLACE(phone, \'[^0-9]\', \'\'),10) AS phone_no, order_timestamp AS order_ts, order_timestamp::DATE AS order_date, UPPER(sku_group) AS sku_group, gross_sales AS sales, quantity AS quantity, combined_order_name::VARCHAR AS order_id, \'Online\' AS channel, \'Shopify\' AS store FROM snitch_db.maplemonk.fact_items_snitch WHERE UPPER(sku_group) LIKE \'%4MSFR%\' UNION ALL SELECT \'+91\' || RIGHT( REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10 ) AS phone_no, order_timestamp AS order_ts, order_timestamp::DATE AS order_date, UPPER(sku_group) AS sku_group, selling_price AS sales, suborder_quantity AS quantity, order_name::VARCHAR AS order_id, \'Offline\' AS channel, marketplace_mapped AS store FROM snitch_db.maplemonk.store_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' AND UPPER(sku_group) LIKE \'%4MSFR%\' ), clean_orders AS ( SELECT * FROM perfume_orders WHERE LENGTH(phone_no) = 13 AND phone_no NOT IN ( \'+911234567890\', \'+911234567891\', \'+910123456789\', \'+911111111111\', \'+912727272727\', \'+918888888888\', \'+919999999999\', \'+910000000000\', \'+912424242424\', \'+919909090909\' ) ), first_perfume_order AS ( SELECT phone_no, sku_group AS acq_sku_group, order_ts AS first_order_timestamp, order_date AS first_order_date, channel AS acq_channel, store AS acq_store FROM clean_orders QUALIFY ROW_NUMBER() OVER ( PARTITION BY phone_no ORDER BY order_ts ASC, COALESCE(order_id, \'\') ASC, sku_group ASC ) = 1 ), customer_sales AS ( SELECT phone_no, SUM( CASE WHEN channel = \'Online\' THEN sales ELSE 0 END ) AS online_sales, SUM( CASE WHEN channel = \'Offline\' THEN sales ELSE 0 END ) AS offline_sales FROM clean_orders GROUP BY 1 ) SELECT a.phone_no, a.acq_sku_group AS sku_group, a.first_order_date, a.acq_store AS store, a.acq_channel, COALESCE(s.online_sales, 0) AS online_sales, COALESCE(s.offline_sales, 0) AS offline_sales, CASE WHEN COALESCE(s.online_sales, 0) >= COALESCE(s.offline_sales, 0) THEN \'Shopify\' ELSE \'Stores\' END AS customer_main_channel FROM first_perfume_order a LEFT JOIN customer_sales s ON a.phone_no = s.phone_no ; CREATE OR REPLACE TABLE snitch_db.maplemonk.perfumes_retention_overall_sku_level AS WITH orders_union AS ( SELECT \'+91\' || RIGHT( REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10 ) AS phone_no, order_timestamp::DATE AS order_date, UPPER(sku_group) AS order_sku_group, SUM(gross_sales) AS sales, SUM(quantity) AS quantity, COUNT(DISTINCT combined_order_name) AS orders, \'Online\' AS order_store FROM snitch_db.maplemonk.fact_items_snitch WHERE UPPER(sku_group) LIKE \'%4MSFR%\' AND order_timestamp::DATE >= \'2024-01-01\' GROUP BY 1,2,3 UNION ALL SELECT \'+91\' || RIGHT( REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10 ) AS phone_no, order_timestamp::DATE AS order_date, UPPER(sku_group) AS order_sku_group, SUM(selling_price) AS sales, SUM(suborder_quantity) AS quantity, COUNT(DISTINCT order_name) AS orders, \'Offline\' AS order_store FROM snitch_db.maplemonk.store_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' AND UPPER(sku_group) LIKE \'%4MSFR%\' AND order_timestamp::DATE >= \'2024-01-01\' GROUP BY 1,2,3 ), orders_clean AS ( SELECT phone_no, order_date, order_store, order_sku_group, SUM(sales) AS sales, SUM(quantity) AS quantity, SUM(orders) AS orders FROM orders_union WHERE LENGTH(phone_no) = 13 AND phone_no NOT IN ( \'+911234567890\', \'+911234567891\', \'+910123456789\', \'+911111111111\', \'+912727272727\', \'+918888888888\', \'+919999999999\', \'+910000000000\', \'+912424242424\', \'+919909090909\' ) GROUP BY 1,2,3,4 ), cohorts AS ( SELECT phone_no, sku_group AS acq_sku_group, first_order_date, DATE_TRUNC( \'month\', first_order_date ) AS acq_month, acq_channel AS acq_store FROM snitch_db.maplemonk.customer_acq_date_channel_sku WHERE first_order_date >= \'2024-01-01\' ), orders_with_month_diff AS ( SELECT c.phone_no, c.first_order_date, c.acq_month, c.acq_store, c.acq_sku_group, o.order_date, o.order_store, o.order_sku_group, o.sales, o.quantity, o.orders, DATEDIFF( \'month\', c.first_order_date, o.order_date ) AS month_diff FROM cohorts c INNER JOIN orders_clean o ON c.phone_no = o.phone_no AND o.order_date >= c.first_order_date ), views AS ( SELECT \'overall_any_acq_any_repeat\' AS view_type, NULL::VARCHAR AS acq_store_filter, NULL::VARCHAR AS repeat_store_filter UNION ALL SELECT \'online_acq_overall\', \'Online\', NULL UNION ALL SELECT \'offline_acq_overall\', \'Offline\', NULL UNION ALL SELECT \'online_acq_online\', \'Online\', \'Online\' UNION ALL SELECT \'online_acq_offline\', \'Online\', \'Offline\' UNION ALL SELECT \'offline_acq_offline\', \'Offline\', \'Offline\' UNION ALL SELECT \'offline_acq_online\', \'Offline\', \'Online\' ), metrics AS ( SELECT v.view_type, o.acq_month, o.acq_sku_group AS sku_group, COUNT( DISTINCT o.phone_no ) AS acq_customers, SUM( CASE WHEN o.month_diff = 0 AND o.order_sku_group = o.acq_sku_group THEN o.sales ELSE 0 END ) AS acq_sales, SUM( CASE WHEN o.month_diff = 0 AND o.order_sku_group = o.acq_sku_group THEN o.quantity ELSE 0 END ) AS acq_quantity, COUNT( DISTINCT CASE WHEN o.month_diff = 1 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m1_customers, SUM( CASE WHEN o.month_diff = 1 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m1_sales, SUM( CASE WHEN o.month_diff = 1 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m1_quantity, COUNT( DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 3 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m3_customers, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 3 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m3_sales, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 3 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m3_quantity, COUNT( DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 6 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m6_customers, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 6 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m6_sales, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 6 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m6_quantity, COUNT( DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 12 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m12_customers, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 12 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m12_sales, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 12 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m12_quantity, COUNT( DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 18 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m18_customers, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 18 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m18_sales, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 18 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m18_quantity, COUNT( DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 24 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m24_customers, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 24 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m24_sales, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 24 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m24_quantity FROM views v INNER JOIN orders_with_month_diff o ON ( v.acq_store_filter IS NULL OR o.acq_store = v.acq_store_filter ) GROUP BY 1,2,3 ) SELECT view_type, acq_month, sku_group, acq_customers, acq_sales::INT AS acq_sales, acq_quantity::INT AS acq_quantity, m1_customers, m3_customers, m6_customers, m12_customers, m18_customers, m24_customers, DIV0( m1_customers, acq_customers ) AS m1_customer_retention, DIV0( m3_customers, acq_customers ) AS m3_customer_retention, DIV0( m6_customers, acq_customers ) AS m6_customer_retention, DIV0( m12_customers, acq_customers ) AS m12_customer_retention, DIV0( m18_customers, acq_customers ) AS m18_customer_retention, DIV0( m24_customers, acq_customers ) AS m24_customer_retention, DIV0( m1_sales, acq_sales ) AS m1_sales_retention, DIV0( m3_sales, acq_sales ) AS m3_sales_retention, DIV0( m6_sales, acq_sales ) AS m6_sales_retention, DIV0( m12_sales, acq_sales ) AS m12_sales_retention, DIV0( m18_sales, acq_sales ) AS m18_sales_retention, DIV0( m24_sales, acq_sales ) AS m24_sales_retention, DIV0( m1_quantity, acq_quantity ) AS m1_quantity_retention, DIV0( m3_quantity, acq_quantity ) AS m3_quantity_retention, DIV0( m6_quantity, acq_quantity ) AS m6_quantity_retention, DIV0( m12_quantity, acq_quantity ) AS m12_quantity_retention, DIV0( m18_quantity, acq_quantity ) AS m18_quantity_retention, DIV0( m24_quantity, acq_quantity ) AS m24_quantity_retention FROM metrics ORDER BY view_type, acq_month, sku_group ; CREATE OR REPLACE TABLE snitch_db.maplemonk.perfume_retention_datatable AS WITH all_order_items AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, combined_order_name::STRING AS order_id, order_timestamp, order_timestamp::DATE AS order_date, \'Online\' AS channel, UPPER(sku_group) AS sku_group, gross_sales AS sales, quantity, CASE WHEN UPPER(sku_group) LIKE \'%4MSFR%\' THEN 1 ELSE 0 END AS is_perfume, CASE WHEN UPPER(sku_group) NOT LIKE \'%4MSFR%\' OR sku_group IS NULL THEN 1 ELSE 0 END AS is_other FROM snitch_db.maplemonk.fact_items_snitch UNION ALL SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, order_name::STRING AS order_id, order_timestamp, order_timestamp::DATE AS order_date, \'Offline\' AS channel, UPPER(sku_group) AS sku_group, selling_price AS sales, suborder_quantity AS quantity, CASE WHEN UPPER(sku_group) LIKE \'%4MSFR%\' THEN 1 ELSE 0 END AS is_perfume, CASE WHEN UPPER(sku_group) NOT LIKE \'%4MSFR%\' OR sku_group IS NULL THEN 1 ELSE 0 END AS is_other FROM snitch_db.maplemonk.store_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' ), clean_items AS ( SELECT * FROM all_order_items WHERE LENGTH(phone_no) = 13 AND phone_no NOT IN ( \'+911234567890\', \'+911234567891\', \'+910123456789\', \'+911111111111\', \'+912727272727\', \'+918888888888\', \'+919999999999\', \'+910000000000\', \'+912424242424\', \'+919909090909\' ) ), order_level AS ( SELECT phone_no, channel, order_id, order_timestamp, order_date, channel || \'|\' || order_id AS order_key, SUM(sales) AS order_sales, SUM(quantity) AS order_quantity, SUM( CASE WHEN is_perfume = 1 THEN sales ELSE 0 END ) AS perfume_sales, SUM( CASE WHEN is_other = 1 THEN sales ELSE 0 END ) AS other_sales, SUM( CASE WHEN is_perfume = 1 THEN quantity ELSE 0 END ) AS perfume_quantity, MAX(is_perfume) AS has_perfume, MAX(is_other) AS has_other FROM clean_items GROUP BY 1,2,3,4,5 ), company_acq AS ( SELECT phone_no, order_key AS company_acq_order_key, order_date AS company_acq_date, order_timestamp AS company_acq_timestamp, channel AS company_acq_channel, order_sales AS company_acq_order_sales, has_perfume AS company_acq_has_perfume, has_other AS company_acq_has_other FROM order_level QUALIFY ROW_NUMBER() OVER ( PARTITION BY phone_no ORDER BY order_timestamp, order_key ) = 1 ), perfume_acq AS ( SELECT phone_no, order_key AS perfume_acq_order_key, order_date AS perfume_acq_date, order_timestamp AS perfume_acq_timestamp, channel AS perfume_acq_channel, order_sales AS perfume_acq_order_sales, perfume_sales AS perfume_acq_perfume_sales, perfume_quantity AS perfume_acq_quantity, has_other AS perfume_acq_has_other FROM order_level WHERE has_perfume = 1 QUALIFY ROW_NUMBER() OVER ( PARTITION BY phone_no ORDER BY order_timestamp, order_key ) = 1 ), customer_base AS ( SELECT c.phone_no, c.company_acq_date, c.company_acq_timestamp, c.company_acq_channel, c.company_acq_order_key, c.company_acq_order_sales, p.perfume_acq_date, p.perfume_acq_timestamp, p.perfume_acq_channel, p.perfume_acq_order_key, p.perfume_acq_order_sales, p.perfume_acq_perfume_sales, p.perfume_acq_quantity, p.perfume_acq_has_other, CASE WHEN p.phone_no IS NULL THEN 0 ELSE 1 END AS has_ever_bought_perfume, DATEDIFF( \'day\', c.company_acq_date, p.perfume_acq_date ) AS days_company_to_perfume, CASE WHEN p.phone_no IS NULL THEN \'NEVER_BOUGHT_PERFUME\' WHEN c.company_acq_order_key = p.perfume_acq_order_key THEN \'ACQUIRED_WITH_PERFUME\' ELSE \'EXISTING_TO_PERFUME\' END AS perfume_customer_type FROM company_acq c LEFT JOIN perfume_acq p ON c.phone_no = p.phone_no ), post_perfume_orders AS ( SELECT b.phone_no, b.perfume_acq_date, b.perfume_acq_timestamp, b.perfume_acq_channel, o.order_key, o.order_date, o.order_timestamp, o.channel AS repeat_channel, o.order_sales, o.order_quantity, o.perfume_sales, o.perfume_quantity, o.has_perfume, o.has_other, DATEDIFF( \'day\', b.perfume_acq_date, o.order_date ) AS days_after_perfume FROM customer_base b INNER JOIN order_level o ON b.phone_no = o.phone_no AND o.order_key <> b.perfume_acq_order_key AND o.order_timestamp > b.perfume_acq_timestamp WHERE b.has_ever_bought_perfume = 1 ), first_repeat AS ( SELECT phone_no, order_date AS first_repeat_date, order_timestamp AS first_repeat_timestamp, repeat_channel AS first_repeat_channel, DATEDIFF( \'day\', perfume_acq_date, order_date ) AS days_to_first_repeat, CASE WHEN has_perfume = 1 AND has_other = 1 THEN \'PERFUME_AND_OTHER\' WHEN has_perfume = 1 THEN \'PERFUME\' ELSE \'OTHER\' END AS first_repeat_category FROM post_perfume_orders QUALIFY ROW_NUMBER() OVER ( PARTITION BY phone_no ORDER BY order_timestamp, order_key ) = 1 ), retention_metrics AS ( SELECT phone_no, 1 AS any_repeat_ever, MAX(has_perfume) AS perfume_repeat_ever, MAX(has_other) AS other_category_repeat_ever, MAX( CASE WHEN repeat_channel <> perfume_acq_channel THEN 1 ELSE 0 END ) AS cross_channel_ever, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 30 THEN 1 ELSE 0 END ) AS any_repeat_30d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 30 AND has_perfume = 1 THEN 1 ELSE 0 END ) AS perfume_repeat_30d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 30 AND has_other = 1 THEN 1 ELSE 0 END ) AS other_repeat_30d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 30 AND repeat_channel = perfume_acq_channel THEN 1 ELSE 0 END ) AS same_channel_30d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 30 AND repeat_channel <> perfume_acq_channel THEN 1 ELSE 0 END ) AS cross_channel_30d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 60 THEN 1 ELSE 0 END ) AS any_repeat_60d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 60 AND has_perfume = 1 THEN 1 ELSE 0 END ) AS perfume_repeat_60d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 60 AND has_other = 1 THEN 1 ELSE 0 END ) AS other_repeat_60d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 60 AND repeat_channel = perfume_acq_channel THEN 1 ELSE 0 END ) AS same_channel_60d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 60 AND repeat_channel <> perfume_acq_channel THEN 1 ELSE 0 END ) AS cross_channel_60d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 90 THEN 1 ELSE 0 END ) AS any_repeat_90d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 90 AND has_perfume = 1 THEN 1 ELSE 0 END ) AS perfume_repeat_90d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 90 AND has_other = 1 THEN 1 ELSE 0 END ) AS other_repeat_90d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 90 AND repeat_channel = perfume_acq_channel THEN 1 ELSE 0 END ) AS same_channel_90d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 90 AND repeat_channel <> perfume_acq_channel THEN 1 ELSE 0 END ) AS cross_channel_90d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 180 THEN 1 ELSE 0 END ) AS any_repeat_180d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 180 AND has_perfume = 1 THEN 1 ELSE 0 END ) AS perfume_repeat_180d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 180 AND has_other = 1 THEN 1 ELSE 0 END ) AS other_repeat_180d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 180 AND repeat_channel = perfume_acq_channel THEN 1 ELSE 0 END ) AS same_channel_180d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 180 AND repeat_channel <> perfume_acq_channel THEN 1 ELSE 0 END ) AS cross_channel_180d, COUNT(DISTINCT order_key) AS repeat_orders_ever, COUNT(DISTINCT CASE WHEN days_after_perfume BETWEEN 0 AND 30 THEN order_key END ) AS repeat_orders_30d, COUNT(DISTINCT CASE WHEN days_after_perfume BETWEEN 0 AND 60 THEN order_key END ) AS repeat_orders_60d, COUNT(DISTINCT CASE WHEN days_after_perfume BETWEEN 0 AND 90 THEN order_key END ) AS repeat_orders_90d, SUM(order_sales) AS repeat_sales_ever, SUM( CASE WHEN days_after_perfume BETWEEN 0 AND 30 THEN order_sales ELSE 0 END ) AS repeat_sales_30d, SUM( CASE WHEN days_after_perfume BETWEEN 0 AND 60 THEN order_sales ELSE 0 END ) AS repeat_sales_60d, SUM( CASE WHEN days_after_perfume BETWEEN 0 AND 90 THEN order_sales ELSE 0 END ) AS repeat_sales_90d FROM post_perfume_orders GROUP BY 1 ) SELECT b.phone_no, b.company_acq_date, DATE_TRUNC(\'month\', b.company_acq_date) AS company_acq_month, b.company_acq_channel, b.has_ever_bought_perfume, b.perfume_customer_type, b.days_company_to_perfume, b.perfume_acq_date, DATE_TRUNC(\'month\', b.perfume_acq_date) AS perfume_acq_month, b.perfume_acq_channel, b.perfume_acq_order_sales, b.perfume_acq_perfume_sales, b.perfume_acq_quantity, CASE WHEN b.perfume_acq_has_other = 1 THEN \'PERFUME_WITH_OTHER\' WHEN b.has_ever_bought_perfume = 1 THEN \'PERFUME_ONLY\' END AS perfume_acq_order_type, f.first_repeat_date, f.days_to_first_repeat, f.first_repeat_channel, f.first_repeat_category, CASE WHEN f.first_repeat_channel IS NULL THEN \'NO_REPEAT\' WHEN f.first_repeat_channel = b.perfume_acq_channel THEN \'SAME_CHANNEL\' ELSE \'CROSS_CHANNEL\' END AS first_repeat_channel_type, CASE WHEN b.perfume_acq_channel = \'Online\' AND f.first_repeat_channel = \'Offline\' THEN \'ONLINE_TO_OFFLINE\' WHEN b.perfume_acq_channel = \'Offline\' AND f.first_repeat_channel = \'Online\' THEN \'OFFLINE_TO_ONLINE\' WHEN b.perfume_acq_channel = f.first_repeat_channel THEN b.perfume_acq_channel || \'_TO_\' || f.first_repeat_channel WHEN f.first_repeat_channel IS NULL THEN \'NO_REPEAT\' END AS first_repeat_journey, COALESCE(r.any_repeat_ever,0) AS any_repeat_ever, COALESCE(r.perfume_repeat_ever,0) AS perfume_repeat_ever, COALESCE(r.other_category_repeat_ever,0) AS other_category_repeat_ever, COALESCE(r.cross_channel_ever,0) AS cross_channel_ever, COALESCE(r.any_repeat_30d,0) AS any_repeat_30d, COALESCE(r.perfume_repeat_30d,0) AS perfume_repeat_30d, COALESCE(r.other_repeat_30d,0) AS other_repeat_30d, COALESCE(r.same_channel_30d,0) AS same_channel_30d, COALESCE(r.cross_channel_30d,0) AS cross_channel_30d, COALESCE(r.any_repeat_60d,0) AS any_repeat_60d, COALESCE(r.perfume_repeat_60d,0) AS perfume_repeat_60d, COALESCE(r.other_repeat_60d,0) AS other_repeat_60d, COALESCE(r.same_channel_60d,0) AS same_channel_60d, COALESCE(r.cross_channel_60d,0) AS cross_channel_60d, COALESCE(r.any_repeat_90d,0) AS any_repeat_90d, COALESCE(r.perfume_repeat_90d,0) AS perfume_repeat_90d, COALESCE(r.other_repeat_90d,0) AS other_repeat_90d, COALESCE(r.same_channel_90d,0) AS same_channel_90d, COALESCE(r.cross_channel_90d,0) AS cross_channel_90d, COALESCE(r.any_repeat_180d,0) AS any_repeat_180d, COALESCE(r.perfume_repeat_180d,0) AS perfume_repeat_180d, COALESCE(r.other_repeat_180d,0) AS other_repeat_180d, COALESCE(r.same_channel_180d,0) AS same_channel_180d, COALESCE(r.cross_channel_180d,0) AS cross_channel_180d, COALESCE(r.repeat_orders_ever,0) AS repeat_orders_ever, COALESCE(r.repeat_orders_30d,0) AS repeat_orders_30d, COALESCE(r.repeat_orders_60d,0) AS repeat_orders_60d, COALESCE(r.repeat_orders_90d,0) AS repeat_orders_90d, COALESCE(r.repeat_sales_ever,0) AS repeat_sales_ever, COALESCE(r.repeat_sales_30d,0) AS repeat_sales_30d, COALESCE(r.repeat_sales_60d,0) AS repeat_sales_60d, COALESCE(r.repeat_sales_90d,0) AS repeat_sales_90d FROM customer_base b LEFT JOIN first_repeat f ON b.phone_no = f.phone_no LEFT JOIN retention_metrics r ON b.phone_no = r.phone_no ; create or replace table snitch_db.maplemonk.customer_acq_date_channel1 as WITH online_acq AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, \'Shopify\' AS store, MIN(order_timestamp) AS online_acq FROM snitch_db.maplemonk.fact_items_snitch where upper(sku_group) like \'%4MSFR%\' and order_date >= \'2024-01-01\' GROUP BY 1 ), offline_acq AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, marketplace_mapped AS store, order_timestamp AS offline_acq FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' and upper(sku_group) like \'%4MSFR%\' and order_date >= \'2024-01-01\' QUALIFY ROW_NUMBER() OVER (PARTITION BY \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) ORDER BY order_timestamp ASC) = 1 ), online_sales as ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, sum(gross_sales) AS online_sales FROM snitch_db.maplemonk.fact_items_snitch where upper(sku_group) like \'%4MSFR%\' and order_date >= \'2024-01-01\' GROUP BY 1 ), offline_sales as ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, sum(selling_price) as offline_sales FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' and upper(sku_group) like \'%4MSFR%\' and order_date >= \'2024-01-01\' group by 1 ), combined_acq AS ( SELECT phone_no, online_acq AS order_date, store FROM online_acq UNION ALL SELECT phone_no, offline_acq AS order_date, store FROM offline_acq ), final_check as ( SELECT phone_no, order_date::date AS first_order_date, store FROM combined_acq qualify row_number() over (partition by phone_no order by order_date asc) = 1 ) select a.*, ifnull(online_sales,0) as online_sales, ifnull(offline_sales,0) as offline_sales, case when ifnull(online_sales,0)>= ifnull(offline_sales,0) then \'Shopify\' else \'Stores\' end as customer_main_channel from final_check a left join online_sales b on a.phone_no = b.phone_no left join offline_sales c on a.phone_no = c.phone_no where length(a.phone_no) = 13 and a.phone_no not in (\'+911234567890\',\'+911234567891\',\'+910123456789\',\'+911111111111\',\'+912727272727\',\'+918888888888\',\'+919999999999\',\'+910000000000\',\'+912424242424\',\'+919909090909\') ; CREATE OR REPLACE TABLE snitch_db.maplemonk.perfumes_retention_overall AS ( WITH orders_union AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, order_timestamp::date AS order_date, SUM(gross_sales) AS sales, SUM(quantity) AS quantity, COUNT(DISTINCT combined_order_name) AS orders, \'Online\' AS order_store FROM snitch_db.maplemonk.fact_items_snitch where upper(sku_group) like \'%4MSFR%\' and order_date >= \'2024-01-01\' GROUP BY 1,2 UNION ALL SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, order_date, SUM(selling_price) AS sales, SUM(suborder_quantity) AS quantity, COUNT(order_name) AS orders, \'Offline\' AS order_store FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE NOT LOWER(marketplace_mapped) LIKE \'%wh%\' and upper(sku_group) like \'%4MSFR%\' and order_date >= \'2024-01-01\' GROUP BY 1,2 ), orders_clean AS ( SELECT phone_no, order_date, order_store, SUM(sales) AS sales, SUM(quantity) AS quantity, SUM(orders) AS orders FROM orders_union WHERE LENGTH(phone_no) = 13 AND phone_no NOT IN ( \'+911234567890\',\'+911234567891\',\'+910123456789\',\'+911111111111\',\'+912727272727\', \'+918888888888\',\'+919999999999\',\'+910000000000\',\'+912424242424\',\'+919909090909\' ) GROUP BY 1,2,3 ), cohorts AS ( SELECT b.phone_no, b.first_order_date, DATE_TRUNC(\'month\', b.first_order_date) AS acq_month, CASE WHEN b.store = \'Shopify\' THEN \'Online\' ELSE \'Offline\' END AS acq_store FROM snitch_db.maplemonk.customer_acq_date_channel1 b WHERE b.first_order_date IS NOT NULL ), orders_with_month_diff AS ( SELECT c.phone_no, c.first_order_date, c.acq_month, c.acq_store, o.order_date, o.order_store, o.sales, o.quantity, o.orders, DATEDIFF(\'month\', c.first_order_date, o.order_date) AS month_diff FROM cohorts c JOIN orders_clean o ON c.phone_no = o.phone_no ), views AS ( SELECT \'overall_any_acq_any_repeat\' AS view_type, NULL AS acq_store_filter, NULL AS repeat_store_filter UNION ALL SELECT \'online_acq_overall\', \'Online\', NULL UNION ALL SELECT \'offline_acq_overall\', \'Offline\', NULL UNION ALL SELECT \'online_acq_online\', \'Online\', \'Online\' UNION ALL SELECT \'online_acq_offline\', \'Online\', \'Offline\' UNION ALL SELECT \'offline_acq_offline\', \'Offline\', \'Offline\' UNION ALL SELECT \'offline_acq_online\', \'Offline\', \'Online\' ), cohort_sizes AS ( SELECT v.view_type, c.acq_month, COUNT(DISTINCT c.phone_no) AS acq_customers FROM views v JOIN cohorts c ON (v.acq_store_filter IS NULL OR c.acq_store = v.acq_store_filter) GROUP BY 1,2 ), acq_metrics AS ( SELECT v.view_type, o.acq_month, SUM(CASE WHEN o.month_diff = 0 THEN o.sales END) AS acq_sales, SUM(CASE WHEN o.month_diff = 0 THEN o.quantity END) AS acq_quantity FROM views v JOIN orders_with_month_diff o ON (v.acq_store_filter IS NULL OR o.acq_store = v.acq_store_filter) GROUP BY 1,2 ), repeat_metrics AS ( SELECT v.view_type, o.acq_month, COUNT(DISTINCT CASE WHEN o.month_diff = 1 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m1_customers, SUM(CASE WHEN o.month_diff = 1 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m1_sales, SUM(CASE WHEN o.month_diff = 1 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m1_quantity, COUNT(DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 3 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m3_customers, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 3 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m3_sales, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 3 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m3_quantity, COUNT(DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 6 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m6_customers, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 6 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m6_sales, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 6 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m6_quantity, COUNT(DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 12 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m12_customers, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 12 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m12_sales, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 12 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m12_quantity, COUNT(DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 18 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m18_customers, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 18 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m18_sales, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 18 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m18_quantity, COUNT(DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 24 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m24_customers, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 24 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m24_sales, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 24 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m24_quantity FROM views v JOIN orders_with_month_diff o ON (v.acq_store_filter IS NULL OR o.acq_store = v.acq_store_filter) GROUP BY 1,2 ), final AS ( SELECT cs.view_type, cs.acq_month, cs.acq_customers, am.acq_sales, am.acq_quantity, COALESCE(rm.m1_customers,0) AS m1_customers, COALESCE(rm.m3_customers,0) AS m3_customers, COALESCE(rm.m6_customers,0) AS m6_customers, COALESCE(rm.m12_customers,0) AS m12_customers, COALESCE(rm.m18_customers,0) AS m18_customers, COALESCE(rm.m24_customers,0) AS m24_customers, COALESCE(rm.m1_sales,0) AS m1_sales, COALESCE(rm.m3_sales,0) AS m3_sales, COALESCE(rm.m6_sales,0) AS m6_sales, COALESCE(rm.m12_sales,0) AS m12_sales, COALESCE(rm.m18_sales,0) AS m18_sales, COALESCE(rm.m24_sales,0) AS m24_sales, COALESCE(rm.m1_quantity,0) AS m1_quantity, COALESCE(rm.m3_quantity,0) AS m3_quantity, COALESCE(rm.m6_quantity,0) AS m6_quantity, COALESCE(rm.m12_quantity,0) AS m12_quantity, COALESCE(rm.m18_quantity,0) AS m18_quantity, COALESCE(rm.m24_quantity,0) AS m24_quantity FROM cohort_sizes cs LEFT JOIN acq_metrics am ON cs.view_type = am.view_type AND cs.acq_month = am.acq_month LEFT JOIN repeat_metrics rm ON cs.view_type = rm.view_type AND cs.acq_month = rm.acq_month ) SELECT view_type, acq_month, acq_customers, acq_sales::int AS acq_sales, acq_quantity::int AS acq_quantity, DIV0(m1_customers, acq_customers) AS m1_customer_retention, DIV0(m3_customers, acq_customers) AS m3_customer_retention, DIV0(m6_customers, acq_customers) AS m6_customer_retention, DIV0(m12_customers, acq_customers) AS m12_customer_retention, DIV0(m18_customers, acq_customers) AS m18_customer_retention, DIV0(m24_customers, acq_customers) AS m24_customer_retention, DIV0(m1_sales, acq_sales) AS m1_sales_retention, DIV0(m3_sales, acq_sales) AS m3_sales_retention, DIV0(m6_sales, acq_sales) AS m6_sales_retention, DIV0(m12_sales, acq_sales) AS m12_sales_retention, DIV0(m18_sales, acq_sales) AS m18_sales_retention, DIV0(m24_sales, acq_sales) AS m24_sales_retention, DIV0(m1_quantity, acq_quantity) AS m1_quantity_retention, DIV0(m3_quantity, acq_quantity) AS m3_quantity_retention, DIV0(m6_quantity, acq_quantity) AS m6_quantity_retention, DIV0(m12_quantity, acq_quantity) AS m12_quantity_retention, DIV0(m18_quantity, acq_quantity) AS m18_quantity_retention, DIV0(m24_quantity, acq_quantity) AS m24_quantity_retention FROM final ORDER BY view_type, acq_month );",
                    "transaction": true
